import { readFileSync } from "node:fs";
import { RiskLevel } from "@modules/risk/domain/fire-risk.js";

/**
 * How often each land cover × slope combination burned in Turkey, measured from
 * EFFIS burnt areas. Generated by scripts/risk/derive-burn-rates.mjs; do not edit
 * burn-rates.json by hand, re-run the script instead.
 */
type SlopeCell = {
  areaPx: number;
  burnedPx: number;
  ratio: number | null;
  /** ratio actually used: the cell's own, or the class ratio when the sample is too small */
  used: number | null;
};

type BurnRates = {
  generatedAt: string;
  years: number[];
  slopeBinsPct: number[];
  minBurnedPx: number;
  levelThresholds: { basis: string; values: number[] };
  holdout: {
    trainYears: number[];
    testYear: number;
    burnedPxShareByLevel: number[];
    landShareByLevel: number[];
  };
  classes: Record<
    string,
    { areaPx: number; burnedPx: number; ratio: number | null; bySlope: SlopeCell[] }
  >;
};

export const BURN_RATES: BurnRates = JSON.parse(
  readFileSync(new URL("./burn-rates.json", import.meta.url), "utf8"),
);

export const WORLD_COVER_LABELS: Record<number, string> = {
  10: "Tree cover",
  20: "Shrubland",
  30: "Grassland",
  40: "Cropland",
  50: "Built-up",
  60: "Bare / sparse vegetation",
  70: "Snow and ice",
  80: "Permanent water bodies",
  90: "Herbaceous wetland",
  95: "Mangroves",
  100: "Moss and lichen",
};

const LEVELS: RiskLevel[] = ["very_low", "low", "moderate", "high", "very_high"];

/** Index into slopeBinsPct (0-5, 5-15, 15-25, 25-35, >35 % → 0..4). */
export function slopeBin(slopeDeg: number): number {
  const pct = Math.tan((slopeDeg * Math.PI) / 180) * 100;
  const i = BURN_RATES.slopeBinsPct.findIndex((upper) => pct < upper);
  return i === -1 ? BURN_RATES.slopeBinsPct.length : i;
}

/**
 * Burn ratio for a point: 1 = burns as often as the Turkish average.
 * slopeDeg = null (no DEM coverage) falls back to the land cover class ratio.
 * Returns null for classes that do not occur in Turkey's land.
 */
export function burnRatio(
  worldCoverClass: number,
  slopeDeg: number | null,
): number | null {
  const entry = BURN_RATES.classes[String(worldCoverClass)];
  if (!entry) return null;
  if (slopeDeg === null) return entry.ratio;
  return entry.bySlope[slopeBin(slopeDeg)]?.used ?? entry.ratio;
}

/** Level from Turkey's land area quintiles: each level covers 20 % of the land. */
export function structuralLevel(ratio: number): RiskLevel {
  const i = BURN_RATES.levelThresholds.values.findIndex((t) => ratio < t);
  return LEVELS[i === -1 ? LEVELS.length - 1 : i]!;
}
